input.content:
@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: #2b3236;
  background: #ffffff;
}

a {
  color: inherit;
}

/* Header, hero, and feature row share one centered column with the same side padding, so their edges line up. */
.site-header,
.hero,
.points {
  max-width: 1120px;
  margin: 0 auto;
  padding-left: 64px;
  padding-right: 64px;
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 8px 28px;
  padding-top: 22px;
  padding-bottom: 22px;
}

.logo {
  font-size: 19px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 28px;
}

.site-nav a {
  text-decoration: none;
  color: #4d585e;
}

/* Three equal columns: the hero text takes the first two, today's tides the third.
   The feature row below uses the same three columns. */
.hero,
.points {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  column-gap: 48px;
}

.hero {
  align-items: start;
  padding-top: 72px;
  padding-bottom: 96px;
}

.hero-text {
  grid-column: 1 / span 2;
  max-width: 460px;
}

h1 {
  margin: 0 0 16px;
  font-size: 30px;
  font-weight: 500;
  line-height: 1.25;
}

/* "pretty" asks the browser to avoid a single word alone on the last line. */
p {
  text-wrap: pretty;
}

.hero-text p {
  margin: 0 0 24px;
  color: #4d585e;
}

.button {
  display: inline-block;
  padding: 11px 20px;
  border-radius: 6px;
  background: #1f5f7a;
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

/* Today's tides, set as the page Tidewell posts. */
.today {
  grid-column: 3;
  padding: 24px;
  border-radius: 6px;
  background: #f3f5f6;
}

h2 {
  margin: 0 0 12px;
  font-size: 19px;
  font-weight: 500;
  line-height: 1.3;
}

table {
  width: 100%;
  border-collapse: collapse;
  /* Equal-width digits so the times and heights line up down each column. */
  font-variant-numeric: tabular-nums;
}

th,
td {
  padding: 8px 0;
  text-align: left;
  font-weight: 400;
  border-bottom: 1px solid #dde2e5;
}

th {
  padding-top: 0;
  color: #4d585e;
}

tbody tr:last-child td {
  border-bottom: none;
  padding-bottom: 0;
}

/* Times and heights are numbers to compare, so they sit right-aligned. */
th:nth-child(n + 2),
td:nth-child(n + 2) {
  text-align: right;
}

td:nth-child(2) {
  font-weight: 500;
}

.points {
  row-gap: 24px;
  padding-bottom: 72px;
}

.point h3 {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 500;
}

.point p {
  margin: 0;
  color: #4d585e;
}

/* Below tablet-landscape width, stack everything in one column. */
@media (max-width: 900px) {
  .hero,
  .points {
    grid-template-columns: 1fr;
  }

  .hero-text,
  .today {
    grid-column: auto;
  }

  .hero {
    row-gap: 40px;
    padding-bottom: 56px;
  }

  .today,
  .point {
    max-width: 460px;
  }
}

@media (max-width: 560px) {
  .site-header,
  .hero,
  .points {
    padding-left: 20px;
    padding-right: 20px;
  }

  .hero {
    padding-top: 40px;
  }

  .today {
    padding: 20px;
  }
}

