tool_input.command:
python3 - <<'EOF'
import re
path = "styles.css"
css = open(path).read()

css = css.replace(""".hero-text {
  grid-column: 1 / span 2;
  max-width: 460px;
}""", """.hero-text {
  grid-column: 1;
}""")

css = css.replace("""/* Three equal columns: the hero text takes the first two, today's tides the third.
   The feature row below uses the same three columns. */""", """/* Three equal columns: the hero text takes the first, today's tides the other two.
   The feature row below uses the same three columns. */""")

css = css.replace(""".today {
  grid-column: 3;""", """.today {
  grid-column: 2 / span 2;""")

css = css.replace(""".point h3 {
  margin: 0 0 4px;
  font-size: 15px;""", """.point h3 {
  margin: 0 0 6px;
  font-size: 19px;
  line-height: 1.3;""")

old_media = css[css.index("/* Below tablet-landscape width"):]
new_media = """/* Tablet: the hero keeps two columns. Each point puts its heading in the
   left column and its text in the right, on the same column lines. */
@media (max-width: 900px) {
  .hero,
  .points {
    grid-template-columns: 1fr 1fr;
  }

  .hero-text {
    grid-column: 1;
  }

  .today {
    grid-column: 2;
  }

  .points {
    row-gap: 28px;
  }

  /* "subgrid" lets the point's heading and text sit on the parent grid's two columns. */
  .point {
    grid-column: 1 / span 2;
    display: grid;
    grid-template-columns: subgrid;
  }

  .point h3 {
    margin: 0;
  }
}

/* Phone: everything in one column. */
@media (max-width: 560px) {
  .site-header,
  .hero,
  .points {
    padding-left: 20px;
    padding-right: 20px;
  }

  .hero,
  .points {
    grid-template-columns: 1fr;
  }

  .hero-text,
  .today,
  .point {
    grid-column: auto;
  }

  .point {
    display: block;
  }

  .point h3 {
    margin: 0 0 6px;
  }

  .hero {
    row-gap: 40px;
    padding-top: 40px;
    padding-bottom: 56px;
  }

  .today {
    padding: 20px;
  }
}
"""
css = css.replace(old_media, new_media)
open(path, "w").write(css)
EOF
